269: inline glm::vec4 getPlayerUV(int row, int col) {
270:   float u = (col * 64.0f) / 832.0f;
271:   float v = (row * 64.0f) / 2944.0f;
272:   float du = 64.0f / 832.0f;
273:   float dv = 64.0f / 2944.0f;
274:   return glm::vec4(u, v, du, dv);
