277: inline glm::vec4 getTilesetUV(int tx, int ty) {
278:   float u = static_cast<float>(tx) / 16.0f;
279:   float v = static_cast<float>(ty) / 16.0f;
280:   float du = 1.0f / 16.0f;
281:   float dv = 1.0f / 16.0f;
282:   return glm::vec4(u, v, du, dv);
283: }
