285: inline glm::vec4 getCoinUV(int frame) {
286:   int f = (frame % 12);
287:   float u = static_cast<float>(f) * (16.0f / 192.0f);
288:   float v = 0.0f;
289:   float du = 16.0f / 192.0f;
290:   float dv = 1.0f;
291:   return glm::vec4(u, v, du, dv);
292: }
