314: inline glm::vec4 getDirectionArrowUV(RunDirection dir) {
315:   int idx = 0;
316:   if (dir == DIR_LEFT)
317:     idx = 0;
318:   else if (dir == DIR_RIGHT)
319:     idx = 1;
320:   else if (dir == DIR_UP)
321:     idx = 2;
322:   else if (dir == DIR_DOWN)
