128:     // 1. SFX_STEP: Subtle crisp footstep thud
129:     {
130:         int count = static_cast<int>(sr * 0.045f);
131:         std::vector<int16_t> samples(count);
132:         for (int i = 0; i < count; ++i) {
133:             float t = (float)i / sr;
134:             float env = 1.0f - ((float)i / count);
135:             float freq = 130.0f - (t * 900.0f);
136:             if (freq < 45.0f) freq = 45.0f;
137:             float s = std::sin(2.0f * PI * freq * t) * env;
138:             samples[i] = static_cast<int16_t>(s * 10500.0f);
139:         }
