250:         std::vector<int16_t> samples(count);
251:         for (int i = 0; i < count; ++i) {
252:             float t = (float)i / count; // 0.0 -> 1.0
253:             float timeSec = (float)i / sr;
254: 
255:             // 1. Blade whoosh envelope: swift rise in first 20ms, then exponential tail
256:             float whooshEnv = (t < 0.12f) ? (t / 0.12f) : std::pow(1.0f - (t - 0.12f) / 0.88f, 1.6f);
257: 
258:             // 2. Frequency sweep: swift aerodynamic cut descending from 2400 Hz down to 320 Hz
259:             float whooshFreq = 2400.0f * std::exp(-timeSec * 18.0f) + 320.0f;
260:             float whooshTone = std::sin(2.0f * PI * whooshFreq * timeSec);
