268:             float ring1 = std::sin(2.0f * PI * 3250.0f * timeSec);
269:             float ring2 = std::sin(2.0f * PI * 4950.0f * timeSec);
270:             float ring3 = std::sin(2.0f * PI * 1920.0f * timeSec);
271:             float steelRing = (ring1 * 0.45f + ring2 * 0.35f + ring3 * 0.20f) * metalEnv;
