275:             float bladeBite = std::sin(2.0f * PI * 1350.0f * timeSec) * transientEnv * 0.45f;
276: 
277:             // Combined sword slash soundwave
278:             float s = (airCut * 0.55f + steelRing * 0.35f + bladeBite * 0.20f);
279:             s = std::max(-1.0f, std::min(1.0f, s * 1.35f));
