698:         // ---------------------------------------------------------------------
699:         // Intro Splash Screen Playback & Rendering
700:         // ---------------------------------------------------------------------
701:         if (currentGameState == STATE_INTRO_SPLASH) {
702:             splashTimer += rawDeltaTime;
703:             if (splashTimer >= SPLASH_TOTAL_DURATION) {
704:                 startIntroVideo();
705:             } else {
706:                 float fadeAlpha = 1.0f;
707:                 if (splashTimer < SPLASH_FADE_IN_TIME) {
708:                     fadeAlpha = splashTimer / SPLASH_FADE_IN_TIME;
709:                 } else if (splashTimer > (SPLASH_TOTAL_DURATION - SPLASH_FADE_OUT_TIME)) {
710:                     fadeAlpha = (SPLASH_TOTAL_DURATION - splashTimer) / SPLASH_FADE_OUT_TIME;
711:                 }
712:                 fadeAlpha = glm::clamp(fadeAlpha, 0.0f, 1.0f);
713: 
714:                 glClearColor(0.02f, 0.02f, 0.03f, 1.0f);
715:                 glClear(GL_COLOR_BUFFER_BIT);
716: 
717:                 glUseProgram(gameRenderer.getProgram());
718: 
719:                 int curFbW = 0, curFbH = 0;
720:                 glfwGetFramebufferSize(window, &curFbW, &curFbH);
721:                 float aspect = (curFbH > 0) ? (static_cast<float>(curFbW) / static_cast<float>(curFbH)) :
722:                                (static_cast<float>(WINDOW_WIDTH) / static_cast<float>(WINDOW_HEIGHT));
723:                 float halfH = 6.8f;
724:                 float halfW = halfH * aspect;
725: 
726:                 float progress = splashTimer / SPLASH_TOTAL_DURATION;
727:                 UIManager::instance().renderSplashScreen(halfW, halfH, fadeAlpha, progress);
728: 
729:                 glfwSwapBuffers(window);
730:                 glfwPollEvents();
731:                 continue;
732:             }
733:         }
734: 
735:         // ---------------------------------------------------------------------
736:         // Intro Video Playback & Cinematic Rendering
737:         // ---------------------------------------------------------------------
738:         if (currentGameState == STATE_INTRO_VIDEO) {
739:             introVideoPlayer.update(rawDeltaTime);
740:             if (introVideoPlayer.hasFinished()) {
741:                 introVideoPlayer.close();
742:                 currentGameState = STATE_RUNNING;
743:                 isGameIdleAtStart = true;
744:                 playerVel = glm::vec2(0.0f, 0.0f);
745:                 if (!hasShownInitialTutorial) {
746:                     showTutorialModal = true;
747:                     hasShownInitialTutorial = true;
748:                     tutorialOpenedFromPause = false;
749:                     tutDismissLast = true;
750:                 }
751:                 audioMgr.startBGM();
752:             } else {
753:                 glClearColor(0.02f, 0.02f, 0.03f, 1.0f);
754:                 glClear(GL_COLOR_BUFFER_BIT);
755: 
756:                 glUseProgram(gameRenderer.getProgram());
757: 
758:                 int curFbW = 0, curFbH = 0;
759:                 glfwGetFramebufferSize(window, &curFbW, &curFbH);
760:                 float aspect = (curFbH > 0) ? (static_cast<float>(curFbW) / static_cast<float>(curFbH)) :
761:                                (static_cast<float>(WINDOW_WIDTH) / static_cast<float>(WINDOW_HEIGHT));
762:                 float halfH  = 6.8f;
763:                 float halfW  = halfH * aspect;
764:                 glm::mat4 identityView = glm::mat4(1.0f);
765:                 glm::mat4 orthoUI = glm::ortho(-halfW, halfW, -halfH, halfH, -1.0f, 1.0f);
766: 
767:                 // 1. Render Video Frame (Fit aspect ratio 16:9 within viewport)
768:                 unsigned int videoTex = introVideoPlayer.getTextureID();
769:                 if (videoTex != 0) {
770:                     float vW = static_cast<float>(introVideoPlayer.getWidth());
771:                     float vH = static_cast<float>(introVideoPlayer.getHeight());
772:                     float videoAspect = (vH > 0.0f) ? (vW / vH) : (16.0f / 9.0f);
773: 
774:                     float quadW = halfW * 2.0f;
775:                     float quadH = quadW / videoAspect;
776:                     if (quadH > halfH * 2.0f) {
777:                         quadH = halfH * 2.0f;
778:                         quadW = quadH * videoAspect;
779:                     }
780: 
781:                     glm::mat4 modelVideo = glm::mat4(1.0f);
782:                     modelVideo = glm::scale(modelVideo, glm::vec3(quadW, quadH, 1.0f));
783:                     glm::vec4 uvRect(0.0f, 0.0f, 1.0f, 1.0f);
784:                     // Pass discardAlpha = false so opaque video frames are never clipped
785:                     gameRenderer.drawQuad(modelVideo, identityView, orthoUI, glm::vec4(1.0f), true, uvRect, videoTex, false);
786:                 }
787: 
788:                 // 2. Cinematic Progress Bar at bottom
789:                 float barW = halfW * 1.7f;
790:                 float barH = 0.07f;
791:                 float barY = -halfH + 0.65f;
792:                 // Bar Background
793:                 glm::mat4 modelBarBg = glm::mat4(1.0f);
794:                 modelBarBg = glm::translate(modelBarBg, glm::vec3(0.0f, barY, 0.0f));
795:                 modelBarBg = glm::scale(modelBarBg, glm::vec3(barW, barH, 1.0f));
796:                 gameRenderer.drawQuad(modelBarBg, identityView, orthoUI, glm::vec4(0.18f, 0.22f, 0.30f, 0.75f), false, glm::vec4(0), 0);
