void AudioManager::applyBgmVolume() {
    int effective = isBgmMuted ? 0 : std::clamp(bgmVolumePercent, 0, 100);
    int mciVol = effective * 10; // MCI volume scale is 0..1000
    char cmd[64];
    std::snprintf(cmd, sizeof(cmd), "setaudio bgm volume to %d", mciVol);
    mciSendStringA(cmd, NULL, 0, NULL);
}

void AudioManager::startBGM() {
    mciSendStringA("close bgm", NULL, 0, NULL);
    mciSendStringA("open \"assets/Quarter_in_the_Slot.mp3\" type mpegvideo alias bgm", NULL, 0, NULL);
    isBgmMuted = (bgmVolumePercent <= 0);
    applyBgmVolume();
    mciSendStringA("play bgm repeat", NULL, 0, NULL);
}

void AudioManager::stopBGM() {
    mciSendStringA("close bgm", NULL, 0, NULL);
}

void AudioManager::setBgmVolumePercent(int percent) {
    int clamped = std::clamp(percent, 0, 100);
    // Snap to 10% increments (0, 10, 20, ..., 100)
    int snapped = ((clamped + 5) / 10) * 10;
    bgmVolumePercent = std::clamp(snapped, 0, 100);
    isBgmMuted = (bgmVolumePercent == 0);
    applyBgmVolume();
}

void AudioManager::adjustBgmVolume(int deltaPercent) {
    int base = isBgmMuted ? 0 : bgmVolumePercent;
    setBgmVolumePercent(base + deltaPercent);
}

void AudioManager::toggleBgmMute() {
    isBgmMuted = !isBgmMuted;
    if (!isBgmMuted && bgmVolumePercent <= 0) {
        bgmVolumePercent = 30;
    }
    applyBgmVolume();
}

