// If Paused: handle Volume Slider (mouse click/drag + Left/Right keys), Resume, and Quit
static bool draggingVolumeSlider = false;
static bool pauseLeftLast = false;
static bool pauseRightLast = false;
static bool pauseMouseLast = false;
if (currentGameState == STATE_PAUSED) {
    bool leftPressed = (glfwGetKey(window, GLFW_KEY_LEFT) == GLFW_PRESS ||
                        glfwGetKey(window, GLFW_KEY_A) == GLFW_PRESS);
    bool rightPressed = (glfwGetKey(window, GLFW_KEY_RIGHT) == GLFW_PRESS ||
                         glfwGetKey(window, GLFW_KEY_D) == GLFW_PRESS);
    if (leftPressed && !pauseLeftLast) {
        audioMgr.adjustBgmVolume(-10);
    }
    if (rightPressed && !pauseRightLast) {
        audioMgr.adjustBgmVolume(10);
    }
    pauseLeftLast = leftPressed;
    pauseRightLast = rightPressed;

    bool mouseDown = (glfwGetMouseButton(window, GLFW_MOUSE_BUTTON_LEFT) == GLFW_PRESS);
    double mx = 0.0, my = 0.0;
    int winW = 0, winH = 0;
    glfwGetCursorPos(window, &mx, &my);
    glfwGetWindowSize(window, &winW, &winH);
    if (winW > 0 && winH > 0) {
        float aspect = static_cast<float>(WINDOW_WIDTH) / static_cast<float>(WINDOW_HEIGHT);
        float halfH = 6.8f;
        float halfW = halfH * aspect;
        float uiX = (static_cast<float>(mx) / static_cast<float>(winW)) * (2.0f * halfW) - halfW;
        float uiY = halfH - (static_cast<float>(my) / static_cast<float>(winH)) * (2.0f * halfH);

        VolumeSliderLayout slider = UIManager::getPauseVolumeSliderLayout();
        if (mouseDown && !pauseMouseLast) {
            float halfBtn = slider.btnSize * 0.6f;
            if (std::abs(uiX - slider.minusBtnX) <= halfBtn &&
                std::abs(uiY - slider.trackY) <= halfBtn) {
                audioMgr.adjustBgmVolume(-10);
            } else if (std::abs(uiX - slider.plusBtnX) <= halfBtn &&
                       std::abs(uiY - slider.trackY) <= halfBtn) {
                audioMgr.adjustBgmVolume(10);
            } else if (uiX >= slider.trackLeft - 0.35f &&
                       uiX <= slider.trackRight + 0.35f &&
                       std::abs(uiY - slider.trackY) <= 0.42f) {
                draggingVolumeSlider = true;
            }
        }
        if (mouseDown && draggingVolumeSlider) {
            float t = std::clamp((uiX - slider.trackLeft) / (slider.trackRight - slider.trackLeft), 0.0f, 1.0f);
            int snappedPercent = static_cast<int>(std::round(t * 10.0f)) * 10;
            if (snappedPercent != audioMgr.getBgmVolumePercent()) {
                audioMgr.setBgmVolumePercent(snappedPercent);
            }
        }
    }
    if (!mouseDown) {
        draggingVolumeSlider = false;
    }
    pauseMouseLast = mouseDown;

    if (glfwGetKey(window, GLFW_KEY_SPACE) == GLFW_PRESS || glfwGetKey(window, GLFW_KEY_ENTER) == GLFW_PRESS) {
        draggingVolumeSlider = false;
        currentGameState = STATE_RUNNING;
    }
    if (glfwGetKey(window, GLFW_KEY_Q) == GLFW_PRESS) {
        glfwSetWindowShouldClose(window, true);
    }
    return;
}
