                        glm::vec4(1.0f, 0.75f, 0.35f, 1.0f), orthoUI);
  curY -= 0.32f;

  gameRenderer.drawText(
      "LIVES  : 3 Hits absorbed before death. Pick up Hearts to restore lives.",
      textX, curY, 0.18f, 0.27f, glm::vec4(1.0f, 0.35f, 0.65f, 1.0f), orthoUI);
  curY -= 0.32f;

  gameRenderer.drawText(
