param(
    [Parameter(Mandatory = $true)]
    [ValidateSet("build", "package")]
    [string]$Action
)

$ErrorActionPreference = "Stop"
$ProgressPreference = "SilentlyContinue"

if ($Action -eq "build") {
    if (!(Test-Path "build")) {
        New-Item -ItemType Directory -Path "build" | Out-Null
    }
    Copy-Item "lib/*.dll" "build/" -Force

    # Prefer native MinGW-w64 compiler over MSYS2 POSIX g++ (/usr/bin/g++.exe)
    $cxx = (Get-Command "x86_64-w64-mingw32-g++.exe" -ErrorAction SilentlyContinue).Source
    if (-not $cxx) {
        $cxx = (Get-Command "g++.exe" -All -ErrorAction SilentlyContinue |
                Where-Object { $_.Source -notmatch '\\msys64\\usr\\bin\\' } |
                Select-Object -First 1).Source
    }
    if (-not $cxx) {
        $cxx = "g++.exe"
    }

    Write-Host "Using compiler: $cxx"
    & $cxx -std=c++17 -Wall -Wextra -O2 -fdiagnostics-color=always -static-libgcc -static-libstdc++ `
        -I./include `
        ./src/main.cpp ./src/VideoPlayer.cpp ./src/Audio.cpp ./src/Renderer.cpp ./src/World.cpp `
        ./src/UIManager.cpp ./src/LadderScene.cpp ./src/SkyFallScene.cpp ./src/glad.c `
        -o ./build/main.exe `
        -Llib -lglfw3 -lopengl32 -lgdi32 -lwinmm -lmfplat -lmfreadwrite -lmfuuid -lole32

    if ($LASTEXITCODE -ne 0) {
        exit $LASTEXITCODE
    }
}
elseif ($Action -eq "package") {
    if (!(Test-Path "build/main.exe")) {
        throw "build/main.exe not found. Run build first."
    }
    if (Test-Path "dist") {
        Remove-Item -Recurse -Force "dist"
    }
    New-Item -ItemType Directory -Force -Path "dist/TheWenderer" | Out-Null
    Copy-Item "build/main.exe" "dist/TheWenderer/TheWenderer.exe" -Force
    if (Test-Path "TheWenderer") {
        Copy-Item "build/main.exe" "TheWenderer/TheWenderer.exe" -Force
    }
    Copy-Item "lib/*.dll" "dist/TheWenderer/" -Force
    Copy-Item "assets" -Recurse "dist/TheWenderer/" -Force
    Compress-Archive -Path "dist/TheWenderer" -DestinationPath "TheWenderer_Standalone.zip" -Force
    Remove-Item -Recurse -Force "dist"
    Write-Host "Standalone package created: TheWenderer_Standalone.zip"
}

