  const TutRow rows[] = {
      {"MODES  : Free Exploration is DEFAULT ([A/D] move). Press [F] to toggle Auto-Run!",
       glm::vec4(0.35f, 1.0f, 0.65f, 1.0f)},
      {"MUSIC  : BGM defaults to 30% volume. Slider in [ESC] Pause (10% steps), [M] Mute.",
       glm::vec4(0.40f, 0.85f, 1.0f, 1.0f)},
